document.addEventListener("click",async l=>{const t=l.target.closest("[data-follow]");if(!t)return;const a=t.dataset.type,i=t.dataset.id;t.disabled=!0;try{const o=await fetch("/api/follow.php",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:a,id:i,csrf_token:window.CSRF_TOKEN})}),e=await o.json();if(!o.ok){alert(e.error||"Action failed.");return}t.textContent=e.following?"Following":"Follow",t.classList.toggle("bg-indigo-600",e.following),t.classList.toggle("text-white",e.following),t.classList.toggle("bg-slate-100",!e.following)}catch(o){alert("Network error, please try again.")}finally{t.disabled=!1}});
